#!/usr/bin/env python3
"""Generate artifacts from hwdb/*.toml (hand facts only; the SDK regdb is not emitted).

Usage: python3 scripts/hwdb_gen.py [c] [rust] [md] [ghidra] [ports] [--check]   (no target = all)
Outputs: hwdb/gen/us48_hwdb.h, hwdb/gen/hwdb.rs, docs/hwdb-map.md, hwdb/gen/ghidra_import_hwdb.py,
         hwdb/gen/ghidra_export_hwdb.py (copy of scripts/ghidra/hwdb_export.py), port table in docs/port-map.md.
--check: fail if a generated file differs from disk (no write). Log: tmp/logs/hwdb_gen.log.
"""
import logging
import pathlib
import re
import sys

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
import hwdb  # noqa: E402

ROOT = hwdb.repo_root()
GEN = ROOT / "hwdb/gen"
HDR = "generated by scripts/hwdb_gen.py from the hwdb TOML files, do not edit"
PORT_BEGIN, PORT_END = "<!-- hwdb:ports begin (generated by scripts/hwdb_gen.py, do not edit) -->", "<!-- hwdb:ports end -->"
WRITES = {}


def ident(s):
    return re.sub(r"\W", "_", s).upper()


def put(path, text):
    WRITES[pathlib.Path(path)] = text


def iter_blocks(db):
    return sorted(db.hand_blocks(), key=lambda b: (b.space, b.base, b.name))


def gen_c(db):
    o = ["/* %s */" % HDR, "#ifndef US48_HWDB_H", "#define US48_HWDB_H", "",
         "/* Bases are absolute in the block's space (axi0 = unit 0 AXI/physical); register values are offsets from the block base. */", ""]
    for g in sorted(db.regions.values(), key=lambda g: (g.space, g.base)):
        o.append("/* region %s (%s): %s [%s] */" % (g.name, g.space, g.desc, g.conf))
        o.append("#define HW_%s_BASE\t0x%08xU" % (ident(g.name), g.base))
        if g.size:
            o.append("#define HW_%s_SIZE\t0x%xU" % (ident(g.name), g.size))
    o.append("")
    for b in iter_blocks(db):
        n = "HW_" + ident(b.name)
        o.append("/* block %s (%s): %s [%s] */" % (b.name, b.space, b.desc, b.conf))
        o.append("#define %s_BASE\t0x%08xU" % (n, b.base))
        if b.size:
            o.append("#define %s_SIZE\t0x%xU" % (n, b.size))
        for r in sorted(b.regs.values(), key=lambda r: r.offset):
            rn = "%s_%s" % (n, ident(r.name))
            o.append("#define %s\t0x%xU" % (rn, r.offset))
            if r.count > 1:
                o.append("#define %s_COUNT\t%d" % (rn, r.count))
                o.append("#define %s_STRIDE\t%d" % (rn, r.stride))
            for f in r.fields:
                fn = "%s_%s" % (rn, ident(f.name))
                o.append("#define %s_SHIFT\t%d" % (fn, f.shift))
                o.append("#define %s_MASK\t0x%xU" % (fn, f.mask))
        o.append("")
    o.append("#endif /* US48_HWDB_H */")
    put(GEN / "us48_hwdb.h", "\n".join(o) + "\n")


def gen_rust(db):
    o = ["// %s" % HDR, "#![allow(dead_code)]", "",
         "// Bases are absolute in the block's space (axi0 = unit 0 AXI/physical); register values are offsets from the block base.", ""]
    for g in sorted(db.regions.values(), key=lambda g: (g.space, g.base)):
        o.append("// region %s (%s) [%s]" % (g.name, g.space, g.conf))
        o.append("pub const HW_%s_BASE: u32 = 0x%08x;" % (ident(g.name), g.base))
        if g.size:
            o.append("pub const HW_%s_SIZE: u32 = 0x%x;" % (ident(g.name), g.size))
    o.append("")
    for b in iter_blocks(db):
        n = "HW_" + ident(b.name)
        o.append("// block %s (%s) [%s]" % (b.name, b.space, b.conf))
        o.append("pub const %s_BASE: u32 = 0x%08x;" % (n, b.base))
        if b.size:
            o.append("pub const %s_SIZE: u32 = 0x%x;" % (n, b.size))
        for r in sorted(b.regs.values(), key=lambda r: r.offset):
            rn = "%s_%s" % (n, ident(r.name))
            o.append("pub const %s: u32 = 0x%x;" % (rn, r.offset))
            if r.count > 1:
                o.append("pub const %s_COUNT: u32 = %d;" % (rn, r.count))
                o.append("pub const %s_STRIDE: u32 = %d;" % (rn, r.stride))
            for f in r.fields:
                fn = "%s_%s" % (rn, ident(f.name))
                o.append("pub const %s_SHIFT: u32 = %d;" % (fn, f.shift))
                o.append("pub const %s_MASK: u32 = 0x%x;" % (fn, f.mask))
        o.append("")
    put(GEN / "hwdb.rs", "\n".join(o))


def md_cell(s):
    return str(s).replace("|", "\\|").replace("\n", " ")


def gen_md(db):
    o = ["<!-- %s -->" % HDR, "# hwdb map (generated)", "",
         "- Source: `hwdb/*.toml` (hand-written facts). Edit there, then `python3 scripts/hwdb_gen.py`. Schema: [hwdb.md](hwdb.md).",
         "- Bulk SDK registers (`regdb/*.tsv`: %d iProc, %d CMIC, %d S-channel regs, %d memories) are merged by `scripts/hwdb.py`, not listed here."
         % (len(db.blocks[hwdb.SDK_IPROC].regs), len(db.blocks[hwdb.SDK_CMIC].regs), len(db.sdk_sbus_regs), len(db.sdk_sbus_mems)),
         "- conf: C = confirmed (source cited), I = inferred.", "", "## Address spaces", "", "| Space | Description |", "|---|---|"]
    for n, s in db.spaces.items():
        o.append("| `%s` | %s |" % (n, md_cell(s["desc"])))
    o += ["", "## Regions", "", "| Region | Space | Base | Size | Kind | conf | Description | Source |", "|---|---|---|---|---|---|---|---|"]
    for g in sorted(db.regions.values(), key=lambda g: (g.space, g.base)):
        o.append("| `%s` | %s | `0x%08x` | %s | %s | %s | %s%s | %s |" % (
            g.name, g.space, g.base, ("`0x%x`" % g.size) if g.size else "?", g.kind, g.conf, md_cell(g.desc),
            (" Note: " + md_cell(g.note)) if g.note else "", md_cell(g.src)))
    o += ["", "## Blocks", "", "| Block | Space | Base | Size | Unit | Regs | conf | Description | Source |", "|---|---|---|---|---|---|---|---|---|"]
    for b in iter_blocks(db):
        o.append("| `%s` | %s | `0x%08x` | %s | %s | %d | %s | %s%s | %s |" % (
            b.name, b.space, b.base, ("`0x%x`" % b.size) if b.size else "?", b.unit if b.unit is not None else "-",
            len(b.regs), b.conf, md_cell(b.desc), (" Note: " + md_cell(b.note)) if b.note else "", md_cell(b.src)))
    o += ["", "## Registers"]
    for b in iter_blocks(db):
        if not b.regs:
            continue
        o += ["", "### %s (`0x%08x`)" % (b.name, b.base), ""]
        if b.like:
            o += ["Same registers as `%s`." % b.like]
            continue
        o += ["| Offset | Name | W | Access | Reset | Fields | conf | Notes | Source |", "|---|---|---|---|---|---|---|---|---|"]
        for r in sorted(b.regs.values(), key=lambda r: r.offset):
            fl = ", ".join("%s[%s]" % (f.name, ("%d:%d" % (f.hi, f.lo)) if f.hi != f.lo else str(f.lo)) for f in r.fields)
            nm = r.name + ("[%d]" % r.count if r.count > 1 else "")
            o.append("| `0x%x` | `%s` | %d | %s | %s | %s | %s | %s%s | %s |" % (
                r.offset, nm, r.width, r.access, ("`0x%x`" % r.reset) if r.reset is not None else "", md_cell(fl), r.conf,
                md_cell(r.desc), (" Note: " + md_cell(r.note)) if r.note else "", md_cell(r.src)))
    for bn in db.binaries.values():
        o += ["", "## Firmware: %s" % bn.name, "", "%s (base `0x%08x`)" % (bn.desc, bn.base), "",
              "| Address | Function | Role | Registers | conf | Source |", "|---|---|---|---|---|---|"]
        for f in sorted(bn.funcs.values(), key=lambda f: f.addr):
            o.append("| `0x%08x` | `%s` | %s | %s | %s | %s |" % (f.addr, f.name, md_cell(f.role),
                                                              md_cell(", ".join(str(x) for x in f.regs)), f.conf, md_cell(f.src)))
    put(ROOT / "docs/hwdb-map.md", "\n".join(o) + "\n")


def phy_cell(p):
    if p["phy"] == "gphy":
        return "integrated GPHY, int bus 0" + (" addr %d" % p["phy_addr"] if "phy_addr" in p else "")
    if p["phy"] == "octal":
        return "octal PHY, ext bus 0" + (" `0x%02x`" % p["phy_addr"] if "phy_addr" in p else "")
    if p["phy"] == "higig":
        return "13G HiGig to the other chip"
    return "%s, no PHY" % ("SFP+" if "SFP+" in p["label"] else "SFP")


def gen_ports(db):
    chip = {0: "unit 0 (BCM53344, host SoC)", 1: "unit 1 (BCM53346, PCIe)"}
    o = [PORT_BEGIN, "",
         "| Front | Panel label | Chip | Logical | Phys | PHY | SerDes lane | SDK name | Linux name | conf |",
         "|---|---|---|---|---|---|---|---|---|---|"]
    for p in db.ports:
        o.append("| %s | %s | %s | %d | %d | %s | %s | %s | %s | %s |" % (
            p["front"] or "-", p["label"], chip[p["unit"]], p["logical"], p["phys"], phy_cell(p), p.get("lane", ""),
            ("`%s`" % p["sdk"]) if "sdk" in p else "", ("`%s`" % p["linux"]) if "linux" in p else "", p["conf"]))
    o += ["", PORT_END]
    path = ROOT / "docs/port-map.md"
    text = path.read_text()
    block = "\n".join(o)
    if PORT_BEGIN in text:
        text = re.sub(re.escape(PORT_BEGIN) + r".*?" + re.escape(PORT_END), lambda m: block, text, flags=re.S)
    else:
        raise SystemExit("docs/port-map.md: port markers missing")
    put(path, text)


def py_lit(x):
    return repr(x)


def gen_ghidra(db):
    regions = [(g.name, g.base, g.size, g.kind, g.desc) for g in db.regions.values() if g.space == "axi0" and g.size]
    blocks = []
    for b in iter_blocks(db):
        if b.space != "axi0" or not b.size:
            continue
        regs = []
        for r in sorted(b.regs.values(), key=lambda r: r.offset):
            regs.append((r.offset, r.name, r.width, r.count, r.stride))
        blocks.append((b.name, b.base, b.size, regs, b.desc))
    funcs = {bn.name: (bn.base, [(f.name, f.addr, f.role) for f in sorted(bn.funcs.values(), key=lambda f: f.addr)])
             for bn in db.binaries.values()}
    src = '''# %(hdr)s
# Ghidra import (PyGhidra / Jython-safe). Run in a program of unit 0's address space (axi0).
# Creates memory blocks for regions, labels for registers, a register struct per dense block, and
# function names/comments from hwdb/fw for the binary whose name matches the program (or arg 1).
# Existing memory blocks/labels/functions are left alone unless named differently (functions are renamed).
# Args: [binary-name]
REGIONS = %(regions)s
BLOCKS = %(blocks)s
FUNCS = %(funcs)s
KIND_PERMS = {"ram": "rw", "l2lock": "rw", "device": "rwv", "flash": "rv", "alias": "rw", "pcie": "rwv", "rom": "rv"}


def dense(regs):
    if len(regs) < 4:
        return False
    span = max(o + 4 * max(c, 1) for o, _, _, c, _ in regs)
    used = sum(4 * max(c, 1) for _, _, _, c, _ in regs)
    return used * 2 >= span and all(w == 32 for _, _, w, _, _ in regs)


def run():
    from ghidra.program.model.data import StructureDataType, UnsignedIntegerDataType, CategoryPath
    from ghidra.program.model.symbol import SourceType
    mem = currentProgram.getMemory()  # noqa: F821
    st = currentProgram.getSymbolTable()  # noqa: F821
    af = currentProgram.getAddressFactory().getDefaultAddressSpace()  # noqa: F821
    dtm = currentProgram.getDataTypeManager()  # noqa: F821
    A = lambda v: af.getAddress(v)

    def free(base, size):
        return not any(b.getStart().getOffset() < base + size and b.getEnd().getOffset() >= base for b in mem.getBlocks())

    n_blk = n_lbl = n_str = 0
    for name, base, size, kind, desc in REGIONS:
        if kind in ("hazard",) or not free(base, size):
            continue
        b = mem.createUninitializedBlock(name, A(base), size, False)
        p = KIND_PERMS.get(kind, "rw")
        b.setRead(True)
        b.setWrite("w" in p)
        b.setExecute(kind in ("flash", "rom"))
        b.setVolatile("v" in p)
        b.setComment(desc)
        n_blk += 1
    for name, base, size, regs, desc in BLOCKS:
        if free(base, size):
            b = mem.createUninitializedBlock(name, A(base), size, False)
            b.setRead(True)
            b.setWrite(True)
            b.setExecute(False)
            b.setVolatile(True)
            b.setComment(desc)
            n_blk += 1
        for off, rn, w, cnt, stride in regs:
            for i in range(max(cnt, 1) if cnt <= 32 else 1):
                nm = "%%s_%%s" %% (name.upper(), rn) + ("_%%d" %% i if cnt > 1 else "")
                try:
                    st.createLabel(A(base + off + i * stride), nm, SourceType.USER_DEFINED)
                    n_lbl += 1
                except Exception as e:  # noqa: BLE001
                    print("label %%s: %%s" %% (nm, e))
        if dense(regs):
            s = StructureDataType(CategoryPath("/hwdb"), name + "_regs", 0)
            pos = 0
            for off, rn, w, cnt, stride in sorted(regs):
                if off < pos or cnt > 32:
                    continue
                if off > pos:
                    s.growStructure(off - pos)
                    pos = off
                for i in range(max(cnt, 1)):
                    s.add(UnsignedIntegerDataType.dataType, 4, rn + ("_%%d" %% i if cnt > 1 else ""), None)
                    pos += 4
            dt = dtm.addDataType(s, None)
            try:
                currentProgram.getListing().createData(A(base), dt)  # noqa: F821
                n_str += 1
            except Exception as e:  # noqa: BLE001
                print("struct %%s: %%s" %% (name, e))
    args = list(getScriptArgs())  # noqa: F821
    prog = currentProgram.getName().lower()  # noqa: F821
    n_fn = 0
    for bn, (base, fl) in FUNCS.items():
        if (args and args[0] != bn) or (not args and bn not in prog):
            continue
        fm = currentProgram.getFunctionManager()  # noqa: F821
        for name, addr, role in fl:
            a = A(addr)
            f = fm.getFunctionAt(a)
            if f is None:
                f = createFunction(a, name)  # noqa: F821
            elif f.getName() != name:
                f.setName(name, SourceType.USER_DEFINED)
            if f is not None and role:
                f.setComment(role)
            n_fn += 1
    print("hwdb import: %%d blocks, %%d labels, %%d structs, %%d functions" %% (n_blk, n_lbl, n_str, n_fn))


try:
    currentProgram  # noqa: F821
except NameError:
    pass
else:
    run()
''' % dict(hdr=HDR, regions=py_lit(regions), blocks=py_lit(blocks), funcs=py_lit(funcs))
    put(GEN / "ghidra_import_hwdb.py", src)
    exp = (ROOT / "scripts/ghidra/hwdb_export.py").read_text()
    put(GEN / "ghidra_export_hwdb.py", "# %s (source: scripts/ghidra/hwdb_export.py)\n" % HDR + exp)


def main(argv):
    log = ROOT / "tmp/logs/hwdb_gen.log"
    log.parent.mkdir(parents=True, exist_ok=True)
    logging.basicConfig(level=logging.INFO, format="%(message)s",
                        handlers=[logging.FileHandler(log), logging.StreamHandler(sys.stdout)])
    check = "--check" in argv
    targets = [a for a in argv[1:] if not a.startswith("--")] or ["c", "rust", "md", "ghidra", "ports"]
    db = hwdb.load()
    err = db.validate()
    if err:
        for e in err:
            logging.info("ERR %s", e)
        return 1
    for t in targets:
        {"c": gen_c, "rust": gen_rust, "md": gen_md, "ghidra": gen_ghidra, "ports": gen_ports}[t](db)
    bad = 0
    for p, text in sorted(WRITES.items()):
        if check:
            if not p.exists() or p.read_text() != text:
                logging.info("STALE %s", p.relative_to(ROOT))
                bad += 1
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(text)
        logging.info("wrote %s (%d lines)", p.relative_to(ROOT), text.count("\n"))
    return 1 if bad else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
